import os, json, sys
sys.path.append('storage/shared/atlas/tools')
import ci_validate

def exists_all(ps): return all(os.path.exists(p) for p in ps)

idx_path = 'storage/shared/atlas/edges/index.json'
def load_idx(p):
    if os.path.exists(p):
        try:
            with open(p, 'r', encoding='utf-8') as f: return json.load(f)
        except Exception: pass
    return {"entries": [], "updated": None}
def norm_ents(d):
    out=[]
    for e in d.get("entries", []):
        if isinstance(e, dict) and "entry_path" in e: out.append({"entry_path": e["entry_path"]})
        elif isinstance(e, dict) and "path" in e:     out.append({"entry_path": e["path"]})
        elif isinstance(e, str):                      out.append({"entry_path": e})
    return out
def save_idx(p, ents):
    from datetime import datetime
    data={"entries": ents, "updated": datetime.utcnow().isoformat()+"Z"}
    os.makedirs(os.path.dirname(p), exist_ok=True)
    with open(p, 'w', encoding='utf-8') as f: json.dump(data, f, ensure_ascii=False, indent=2)

ents = norm_ents(load_idx(idx_path))
before = set(e["entry_path"] for e in ents)
updates = []

z_dir = 'storage/shared/atlas/edges/zephyr/variance_renewal'
z_entry = f'{z_dir}/entry.json'
z_need = [f'{z_dir}/hinge_metrics_pre.csv', f'{z_dir}/hinge_summary_pre.txt', f'{z_dir}/panel_pre.png',
          f'{z_dir}/hinge_metrics_post.csv', f'{z_dir}/hinge_summary_post.txt', f'{z_dir}/panel_post.png']
if os.path.exists(z_entry) and exists_all(z_need) and z_entry not in before:
    ents.append({"entry_path": z_entry}); updates.append({"added": z_entry})
    ents = sorted(ents, key=lambda e: e["entry_path"])
    save_idx(idx_path, ents)

out = ci_validate.run()
print(json.dumps({
    "status":"ok", "updates":updates,
    "ci_entries_found": out.get("entries_found"), "ci_ok": out.get("ok"), "ci_with_errors": out.get("with_errors"),
    "report_json":"storage/shared/atlas/edges/ci_validation_report.json",
    "report_txt":"storage/shared/atlas/edges/ci_validation_report.txt"
}))
